def figure(name,alt,caption):return f'<figure class="figure"><img src="../assets/week5/{name}.svg" alt="{escape(alt,quote=True)}" loading="lazy"><figcaption>{caption}</figcaption></figure>'
def table(head,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+str(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def quick(q,a):return '<div class="quick-check"><p>'+q+'</p><details><summary>Compare your reasoning</summary><p>'+a+'</p></details></div>'
def num(id,label,ans,hint,tol=.001):return f'<div class="question"><label for="{id}">{label}</label><input id="{id}" type="text" inputmode="decimal" autocomplete="off" data-answer="{ans}" data-tolerance="{tol}" data-hint="{escape(hint,quote=True)}" aria-describedby="fb-{id}"><span class="field-feedback" id="fb-{id}" aria-live="polite"></span></div>'
def select(id,label,opts,ans,hint):return f'<div class="question"><label for="{id}">{label}</label><select id="{id}" data-answer="{ans}" data-hint="{escape(hint,quote=True)}" aria-describedby="fb-{id}"><option value="">Choose a response…</option>'+''.join(f'<option value="{v}">{escape(t)}</option>' for v,t in opts)+f'</select><span class="field-feedback" id="fb-{id}" aria-live="polite"></span></div>'
def written(id,label):return f'<div class="question"><label for="{id}">{label}</label><textarea id="{id}" rows="5" data-save></textarea></div>'
def check():return '<div class="actions"><button type="button" data-check>Check this section</button></div><p class="section-feedback" aria-live="polite"></p>'
def progress():return '<div class="progress"><span id="progressText">0 sections checked</span><div class="progress-track" aria-hidden="true"><div class="progress-fill" id="progressFill"></div></div></div>'
def page(path,kind,title,lead,body,tags,store=None,legacy=None,nextlink=None):
 nav=''.join(f'<a href="../{url}"'+(' aria-current="page"' if url==path else '')+'>'+label+'</a>' for label,url in NAV)
 attrs=f' data-answer-store="{store}"'+(f' data-legacy-store="{legacy}"' if legacy else '') if store else ''
 end='<div class="student-bar"><div><label for="studentName">Your name for the printed copy</label><input id="studentName" autocomplete="name"></div><button type="button" data-print-work>Print / save completed work</button><div><p id="saveStatus" class="small save-status" aria-live="polite"></p><p id="printStatus" class="small" role="status"></p></div></div>' if store else '<div class="actions no-print"><button type="button" data-print-page>Print this page</button></div>'
 if nextlink:end+=f'<div class="next"><a href="../index.html">← Course home</a><a href="../{nextlink[1]}">{nextlink[0]} →</a></div>'
 s='<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+f'<meta name="description" content="{escape(lead,quote=True)}"><title>Week 5 {kind} — {escape(title)} | Math in Society</title>'+r'''
<link rel="stylesheet" href="../assets/week5/week5.css"><script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},options:{skipHtmlTags:['script','noscript','style','textarea','pre','code']}};</script><script defer src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-chtml.js"></script><script defer src="../assets/week5/week5.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><a href="../index.html">← MATH&amp; 107 · Math in Society</a><span>Centralia College · Dr Lee</span></header>'''+f'<nav class="unit-nav" aria-label="Week 5 materials">{nav}</nav><main class="wrap" id="main"{attrs}><header class="hero"><div class="eyebrow">Week 5 / {kind}</div><h1>{title}</h1><p class="lead">{lead}</p><div class="meta">'+''.join('<span class="tag">'+x+'</span>' for x in tags)+'</div></header>'+('<p class="print-name" id="printName"></p>' if store else '')+body+end+'<footer class="footer"><span>MATH&amp; 107 · Cybernetics and Feedback</span><a href="../readings/Math107_Chapter_05.pdf">Illustrated chapter, practice, and solutions ↗</a></footer></main></body></html>\n'
 write(path,s)

reading=r'''
<section class="card" id="start-here"><div class="kicker">The mathematical setting</div><h2>A good intention can arrive at the wrong time</h2><p>Imagine adjusting a shower. The water feels cold, so you turn the handle toward hot. The warmer water takes time to reach you. If you turn the handle again before that first change arrives, you may get a very hot surprise. Your goal stayed the same. The information guiding your next move was behind the action.</p><p>This week asks how a system uses information to change what happens next. That is the setting for <em>cybernetics</em>, the study of communication, feedback, and control in machines, living things, and social systems. You do not need engineering, calculus, or a background in complex systems. We will build the ideas from the recursive sequences of Week 1 and the measurements and variation of Weeks 3–4.</p><div class="grid"><div><h3>What you will calculate</h3><ul><li>A difference from a target and a correction.</li><li>A sequence using current information.</li><li>A second sequence using an older report.</li><li>A simple learning update and an uncertainty measure.</li></ul></div><div><h3>What you will explain</h3><ul><li>How a measurement closes a feedback loop.</li><li>Why a correction can overshoot a target.</li><li>How delay differs from random noise.</li><li>What goals and measurements leave out in human systems.</li></ul></div></div><p>Read in order and try each short check before opening its explanation. Use the <a href="../demos/cybernetics.html">explorer</a> to follow each update. The <a href="Math107_Chapter_05.pdf">illustrated chapter</a> includes review exercises and complete solutions. The <a href="../information_cybernetics_timeline.html">history timeline</a> and <a href="../applications/ai_week5.html">information-theory extension</a> give these calculations a wider setting.</p></section>
<nav class="toc card" aria-label="In this reading"><h2>Your route through the week</h2><ol><li><a href="#s1">Read a sequence and its subscripts</a></li><li><a href="#cybernetics">Find the parts of a feedback loop</a></li><li><a href="#s2">Build a correction from an error</a></li><li><a href="#s3">Act on a one-step-old report</a></li><li><a href="#s4">Read the graph and explain overshoot</a></li><li><a href="#s6">Change the strength of the response</a></li><li><a href="#s7">Separate noise, delay, and precision</a></li><li><a href="#three-loops">Compare correction, amplification, and learning</a></li><li><a href="#signals">Connect messages, bits, and decisions</a></li><li><a href="#history">Ask who chooses the target</a></li></ol></nav>
<section class="card" id="s1"><div class="kicker">01 / A familiar starting point</div><h2>A subscript tells you when, not how much to multiply</h2><p>A <em>sequence</em> is an ordered list. A <em>recursive rule</em> tells us how to use earlier values to find a new one. If \(a_0=10\) and \(a_{n+1}=a_n-2\), the list begins \(10,8,6,4,\ldots\). Starting at step 0, three updates take us to \(a_3=4\). There are four listed values but only three changes.</p><p>For our greenhouse, let \(x_n\) mean temperature in degrees Fahrenheit at step \(n\). We will treat each step as one hour. Thus \(x_0=64\) is the starting temperature, \(x_1\) is the temperature after one update, and \(x_2\) is the temperature after two updates. The subscript is a label for time. It is neither an exponent nor a multiplication.</p>'''+figure('subscript-timeline','A timeline labels x minus 1 as the earlier history, x zero as the start, x one as after one update, and x two as after two updates.','Read the index first: previous, current, next. The history value x₋₁ is a temperature before the start, not a negative temperature.')+r'''<div class="example"><h3>Translate the notation before calculating</h3><p>If we are at step \(n=2\), then \(x_{n-1}=x_1\) means the previous temperature, \(x_n=x_2\) means the current temperature, and \(x_{n+1}=x_3\) is the next one we want to find.</p></div>'''+quick(r'A sequence starts at \(a_0=5\) and uses \(a_{n+1}=2a_n\). List the first four values and count the updates.',r'The values are \(5,10,20,40\), labeled \(a_0,a_1,a_2,a_3\). Reaching 40 takes three updates. Each update uses the most recently calculated value.')+r'''</section>
<section class="card" id="cybernetics"><div class="kicker">02 / Close the loop</div><h2>A reading becomes feedback when it changes the next action</h2><p>A thermometer on a wall can display the temperature without controlling anything. A thermostat uses the reading to decide whether to change heating or cooling. That action changes the room, which changes the next reading. Information returns to influence the process that produced it. This returning influence is <em>feedback</em>.</p>'''+figure('feedback-loop','The greenhouse temperature is measured, compared with a 70 degree target, and used to decide an action. Heating or cooling changes the temperature, which is measured again.','The arrows form a loop: the action changes the condition that will supply the next observation.')+table(['Part','Meaning','Greenhouse example'],[['State','The condition that can change','Temperature now'],['Sensor','What measures the condition','Thermometer'],['Reference or target','The desired value','70°F'],['Controller','The rule or decision maker','Compare report with 70; choose correction'],['Actuator','What carries out the action','Heater or cooling fan']])+r'''<p>The <em>state</em> and the <em>measurement</em> need not agree. The state is the temperature actually present now; a measurement is a report about temperature. It might describe an earlier hour or contain an error. Our first model makes them agree so we can see one idea at a time.</p>'''+quick('A sprinkler runs every morning at 6 a.m. A second sprinkler runs when a soil sensor reports dry ground. Which uses soil-moisture feedback?','The second uses the measured outcome to choose its next action. The first follows a fixed schedule. A schedule can still be useful, but it does not check whether the soil needs water.')+r'''</section>
<section class="card" id="s2"><div class="kicker">03 / One change at a time</div><h2>Start here, measure a difference, make a correction</h2><p>Our invented greenhouse starts at 64°F and has target \(r=70\)°F. Its controller corrects half of the reported difference each hour. We assume the equipment can produce that exact net temperature change, in either direction. There is no sunlight, heat loss, equipment limit, or random measurement error in this model. These assumptions make the timing of feedback visible.</p><p>The <em>control error</em> is target minus the report used for the decision. “Error” here means a signed difference, not an arithmetic mistake. A 64°F report gives \(70-64=+6\): the report is below target. A 73°F report gives \(70-73=-3\): the report is above target.</p><div class="formula">\[\text{correction}=k(\text{target}-\text{report}),\qquad \text{next}=\text{current}+\text{correction}.\]</div><p>The <em>response strength</em> \(k\) says how much of that difference we use. With \(k=0.5\), we use one-half of the reported difference. With a current report, the rule becomes</p><div class="formula">\[x_{n+1}=x_n+0.5(70-x_n).\]</div>'''+figure('error-correction','At 64 degrees, the difference to the target 70 is 6. A half-error correction adds 3, reaching 67 and leaving a difference of 3.','Correct half of the remaining difference at each step. The original 6°F gap is not reused forever.')+r'''<div class="example"><h3>Write the first two updates in full</h3><p>First: \(x_1=64+0.5(70-64)=64+3=67\).</p><p>Second: \(x_2=67+0.5(70-67)=67+1.5=68.5\).</p><p>The second correction is smaller because it uses the new temperature, 67. Continue by putting 68.5 into the same rule.</p></div>'''+table(['Update','Current (°F)','Report (°F)','Correction (°F)','Next (°F)'],[['0 → 1','64','64','+3','67'],['1 → 2','67','67','+1.5','68.5'],['2 → 3','68.5','68.5','+0.75','69.25'],['3 → 4','69.25','69.25','+0.375','69.625']])+quick(r'A water level starts at 84 cm, with target 100 cm and \(k=0.25\). Use current reports to find the first two new levels.',r'The first error is 16 cm, so the correction is 4 cm and the level becomes 88 cm. The next error is 12 cm, so the correction is 3 cm and the level becomes 91 cm. Correcting one-quarter of the remaining error leaves three-quarters each time.')+r'''</section>
<section class="card" id="s3"><div class="kicker">04 / Change only the age of the report</div><h2>The new state still starts from now</h2><p>Keep the same target, starting temperature, and response strength. Change only the thermometer’s delivery time. The report available at step \(n\) now describes step \(n-1\). The correction uses the older report, but it is added to the <em>current</em> temperature:</p><div class="formula">\[x_{n+1}=x_n+0.5(70-x_{n-1}).\]</div><p>The two subscripts do different jobs. At step 2, \(x_2\) is where we start the next change, while \(x_1\) supplies the report. We need an earlier history value to begin: assume \(x_{-1}=x_0=64\). This says the greenhouse was also 64°F one hour before our start.</p><div class="example"><h3>Watch the two numbers travel through the rule</h3><p>At step 0: current 64, old report 64, correction +3, so \(x_1=67\).</p><p>At step 1: current 67, old report still 64, correction +3, so \(x_2=70\).</p><p>At step 2: current 70, old report 67, correction +1.5, so \(x_3=71.5\).</p><p>The system has reached its target at step 2. The available report has not caught up, so the next correction carries it beyond 70.</p></div>'''+figure('delay-decision','At step 2 the greenhouse is at 70 degrees, but its available report describes 67 degrees at step 1. The half-error correction is plus 1.5, so the next state is 71.5.','Delay changes the information used to decide; it does not move the starting point of the physical change back into the past.')+table(['Update','Current (°F)','Old report (°F)','Correction (°F)','Next (°F)'],[['0 → 1','64','64','+3','67'],['1 → 2','67','64','+3','70'],['2 → 3','70','67','+1.5','71.5'],['3 → 4','71.5','70','0','71.5'],['4 → 5','71.5','71.5','−0.75','70.75'],['5 → 6','70.75','71.5','−0.75','70'],['6 → 7','70','70.75','−0.375','69.625']])+quick('At step 3, the current temperature is 71.5°F but the old report is 70°F. What correction is made, and what temperature follows?','The reported error is 70 − 70 = 0, so the correction is 0 and the next temperature remains 71.5°F. Zero reported error does not mean the present temperature is at the target.')+r'''</section>
<section class="card" id="s4"><div class="kicker">05 / Read a whole trajectory</div><h2>The graph shows when the direction changes</h2><p>Put step number on the horizontal axis and temperature on the vertical axis. Each dot is a calculated state; connecting segments help your eye follow the sequence. They do not specify exactly how temperature changes within an hour. The dashed horizontal line marks 70°F.</p>'''+figure('immediate-delayed','With current reports, temperatures rise toward 70 from below. With one-step-old reports, temperatures reach 70 at step 2, rise to 71.5 at steps 3 and 4, then fall below 70 and return with smaller swings.','Both paths start at 64°F, use target 70°F and response strength 0.5. Report age is the only difference. The temperature axis begins at 63°F to make the small differences visible.')+r'''<p><em>Overshoot</em> means passing the target. <em>Oscillation</em> means repeated back-and-forth variation. A <em>damped oscillation</em> has a shrinking envelope of departures from the target: compare successive peaks or troughs. Not every single step has to move closer, and two consecutive states can be equal.</p><p>In our delayed sequence, steps 3 and 4 are both 71.5, above the target. Steps 7 and 8 are both 69.625, below it. The sequence continues with smaller swings. The controller is responding to past shortages and excesses after the actual condition has changed.</p><div class="insight"><h3>A graph is evidence about the displayed steps</h3><p>Use the table to explain a particular overshoot. A finite plot alone does not prove what every later value will do. In this fixed mathematical example the oscillation does decay, but a similar-looking short beginning is not a universal guarantee.</p></div>'''+quick('Why does the delayed greenhouse keep heating after reaching 70°F? Name the actual report used.','To calculate x₃, it starts at the current x₂ = 70 but uses the old x₁ = 67 report. Half of the reported 3°F shortage is +1.5°F. It is correcting a shortage that is already gone.')+r'''<p><a href="../demos/cybernetics.html#sequence">Reveal the paths one step at a time in the explorer →</a></p></section>
<section class="card" id="s6"><div class="kicker">06 / The amount of correction also matters</div><h2>Current information can still produce an overreaction</h2><p>A delay can cause a swing, but delay is not the only cause. With current reports and \(k=1.5\), the first correction is \(1.5(70-64)=9\). Starting at 64, the temperature jumps to 73. The next error is −3, the correction is −4.5, and the temperature becomes 68.5. The sequence begins \(64,73,68.5,70.75,\ldots\).</p>'''+figure('strength-comparison','Four panels show immediate feedback for response strengths 0.5, 1.5, 2, and 2.3: approach without crossing, shrinking alternating departures, a persistent two-value cycle, and growing alternating departures.','These four cases use current measurements. Compare panels on the same temperature scale; changing response strength alone can change the behavior.')+r'''<p>There is a short way to understand the immediate rule. If the old gap is \(r-x_n\), the correction removes \(k\) times that gap. The gap left afterward is \((1-k)(r-x_n)\). For \(k=0.5\), one-half of the gap remains on the same side. For \(k=1.5\), the remaining gap is −0.5 times the old one: half the size, on the other side.</p>'''+table(['Strength k','Immediate rule, starting away from the target'],[['0','No correction; the state stays where it starts'],['0 < k < 1','Approaches without crossing'],['1','Reaches the target in one update'],['1 < k < 2','Crosses repeatedly; departures shrink'],['2','Alternates between two equal departures'],['k > 2','Alternating departures grow']])+r'''<p>This table is about this particular rule with <em>current</em> reports. Do not apply its thresholds unchanged to delayed controllers. If the state starts exactly at the target, zero error keeps it there under any of these strengths in the ideal model.</p>'''+quick(r'With target 10, start 0, and current reports, calculate two updates using \(k=1.5\). Is this corrective or amplifying feedback?',r'The states are \(0,15,7.5\). The response is corrective: it opposes the measured departure. It is strong enough to cross the target, so corrective feedback does not guarantee a path without overshoot.')+r'''</section>
<section class="card" id="s7"><div class="kicker">07 / Bring back statistics</div><h2>A late reading and a noisy reading create different problems</h2><p>A delayed report can be perfectly accurate about an earlier hour. A noisy report fluctuates around what it measures. A biased sensor consistently reads too high or too low. A rounded report loses some precision. More than one of these can occur at once.</p>'''+figure('noise-vs-delay','Three reports show different issues: a delayed 67 degree report when the current temperature is 70; a current 72 degree report about a steady 68 degree state; and a sensor consistently reading 2 degrees high.','Ask two separate questions: what time does this report describe, and how well does it describe that time?')+r'''<div class="example"><h3>A z-score judges unusualness under a stated model</h3><p>Suppose a steady 68°F environment produces approximately normal sensor readings with mean 68 and standard deviation 2°F. A reading of 72 has \(z=(72-68)/2=2\). It is two standard deviations above the mean. It is unusual under that model, but it does not by itself prove a temperature change or a broken sensor. Compare the report with other evidence.</p></div><p>For independent, unbiased readings of the same steady condition, averaging \(m\) readings reduces the standard deviation of the average to \(\sigma/\sqrt{m}\). With individual standard deviation 2°F, averages of 1, 4, and 16 readings have standard deviations 2, 1, and 0.5°F. This is variability across repeated averages, not a promise that any particular average is exactly right.</p>'''+figure('averaging','The standard deviation of an average decreases from 2 degrees for one reading to 1 for four readings and 0.5 for sixteen, while the span needed to collect consecutive one-minute readings increases.','If one reading arrives each minute, a batch of m readings spans m − 1 minutes. Precision improves under the steady, independent, unbiased model; the information also covers a longer past interval.')+r'''<p>Averaging cannot remove a shared bias, and correlated readings may provide less improvement. If the temperature is changing while we gather data, an average of past readings is not simply a precise measurement of the present. This creates a practical question: how much information can we gather before the action becomes late?</p>'''+quick('A sensor always reads 2°F too high. Will averaging 16 of its readings remove that 2°F bias?','No. Averaging can reduce independent random variation, but a shared +2°F bias remains. Checking or calibrating the sensor addresses a different problem.')+r'''<p class="small">Reference for the sampling-mean framework: <a href="https://www.itl.nist.gov/div898/handbook/prc/section1/prc14.htm">NIST Engineering Statistics Handbook</a>. The calculation here assumes independent readings of the same steady state.</p></section>
<section class="card" id="three-loops"><div class="kicker">08 / Use the same pattern in different settings</div><h2>Correct, amplify, or adapt</h2><p><em>Corrective</em>, or negative, feedback opposes a measured departure. <em>Amplifying</em>, or positive, feedback reinforces a change. These words describe direction, not whether the result is good or bad. An <em>adaptive</em> system changes its adjustable rule or parameters using information from earlier results. Adaptation is another feature of a system, rather than a third mutually exclusive sign of feedback.</p>'''+figure('feedback-types','A corrective loop reduces a temperature gap, an amplifying loop increases a modeled exposure index, and a learning loop changes an adjustable weight in response to prediction errors.','First ask what the loop does to a departure; then ask whether it can change how it responds.')+r'''<h3>Amplification uses the updated amount</h3><p>Suppose a hypothetical exposure index begins at 100 and grows by 20% per round. The rule \(v_{n+1}=1.2v_n\) gives \(100,120,144,172.8,\ldots\). The second increase is 24, not 20, because the base is now 120. These are index values, so decimals are meaningful. A real count of people is whole, and an actual spreading process has a finite audience and other limits.</p><h3>A learning rule generates a sequence of weights</h3><p>Let a toy predictor use \(\widehat y=2w\), where \(w\) is an adjustable number called a weight and \(\widehat y\) means prediction. The target output is 6. Choose the training rule \(w_{n+1}=w_n+0.25(6-2w_n)\), starting at \(w_0=1\).</p>'''+table(['Attempt n','Weight wₙ','Prediction 2wₙ','Error 6 − prediction','Next weight'],[['0','1','2','4','2'],['1','2','4','2','2.5'],['2','2.5','5','1','2.75'],['3','2.75','5.5','0.5','2.875']])+r'''<p>The successful weight is 3 because \(2(3)=6\). Notice the units of the two goals: a weight of 3 gives a prediction of 6. They are not interchangeable. This one-example model shows how returned information can alter future predictions; it cannot establish success on other examples.</p>'''+quick(r'The current weight is 2.5. Find the prediction, prediction error, and next weight using the rule above.',r'The prediction is 5, the error is 1, and the weight correction is 0.25. The next weight is 2.75, so the next prediction will be 5.5. The prediction error is not added directly to the prediction; the chosen rule first changes the weight.')+r'''<p><a href="../applications/week5_ai.html">Explore learning updates and their timing →</a></p></section>
<section class="card" id="signals"><div class="kicker">09 / Information has to reach the decision</div><h2>A message can be represented, checked, and interpreted</h2><p>The greenhouse thermometer sends a signal to its controller. A digital signal can represent a measurement as a string of bits, each 0 or 1. With 3 bits there are \(2^3=8\) possible patterns. The code must specify what each pattern means; the symbols alone do not supply the interpretation.</p><p>Extra structure can help detect damaged messages. With <em>even parity</em>, append a bit so the total number of 1s is even. The data 1011 has three 1s, so append 1 to get 10111. One flipped bit makes the total odd and signals an error. Two flipped bits can leave the count even. This check detects any single-bit change but does not identify or repair it.</p>'''+figure('bit-parity','Data bits 1011 contain three ones. Appending parity bit 1 makes four ones. A single flipped data bit creates an odd total and can be detected.','More information in the message can help check transmission. Passing this check does not establish that the original sensor reading was timely or accurate.')+r'''<p>Information theory also measures <em>surprise relative to a probability model</em>. An event assigned probability \(p\) has surprisal \(I=-\log_2 p\) bits. You can use powers of two without knowing logarithm techniques: probabilities 1/2, 1/4, and 1/8 correspond to 1, 2, and 3 bits. A less probable event carries more surprise under that model. “More bits” does not by itself mean more truth, social value, or importance.</p><p><em>Entropy</em> is average surprise across possible outcomes. A fair coin has two equally likely outcomes and entropy 1 bit per toss. A coin that always lands heads has entropy 0, since its outcome is certain. The timeline’s coin experiment makes that distinction visible; the optional <a href="../applications/ai_week5.html">AI Mathematics page</a> scores predictions for observed tokens.</p>'''+quick('A signal is assigned probability 1/32. How many bits of surprise does its occurrence carry? Does this tell us whether the sensor was correct?','Since 32 = 2⁵, the surprise is 5 bits. This is a probability-based score, not a check of the sensor’s accuracy, age, or usefulness.')+r'''</section>
<section class="card" id="history"><div class="kicker">10 / Mathematics in society</div><h2>Who sets the target, and who observes the observer?</h2><p>A classroom may use assessment results to change instruction. Students respond to the new instruction and to the assessment itself. Their responses change what the instructor observes next. The observer’s decisions become part of the situation being observed.</p>'''+figure('observer-loop','Assessment results guide changes in teaching; students respond to the changed teaching and assessment; the new results guide the teacher again. Students can also provide feedback about how learning is measured.','In human systems, a measured score is a limited indicator of a larger goal. The choice of target and measurement deserves discussion.')+r'''<p>Norbert Wiener’s 1948 <em>Cybernetics</em> connected communication and control in machines and living systems. Claude Shannon’s 1948 communication theory studied messages, uncertainty, noise, and reliable transmission. These are connected subjects with different central questions.</p><p>Anthropologist Margaret Mead helped bring questions about culture and social organization into the interdisciplinary Macy Conferences. In a 1967 address published in 1968 as <em>Cybernetics of Cybernetics</em>, she asked whether the American Society for Cybernetics could apply cybernetic ideas to its own organization. The people studying feedback could also examine their own feedback loops.</p><p>The <a href="../information_cybernetics_timeline.html">illustrated history</a> preserves a broad cast: human computers, programmers, engineers, mathematicians, psychologists, and organizers. Follow the contributions of Mead, Janet Freed, Rózsa Péter, F. Jessie MacWilliams, Vera Pless, and other women alongside Wiener and Shannon. You are not expected to memorize all 63 entries. Use the guided routes to explain how one historical problem connects to this week’s mathematics.</p><div class="insight"><h3>A model can describe the consequences of a chosen goal</h3><p>It cannot decide by itself whether that goal is fair, whether the measurement represents everything that matters, or whose experience is missing. In a school, a higher test score may be one useful observation; it is not a complete definition of learning.</p></div><p class="small">Historical sources: <a href="https://mitpress.mit.edu/9780262537841/cybernetics-or-control-and-communication-in-the-animal-and-the-machine/">Wiener’s book, MIT Press</a>; <a href="https://www.nokia.com/bell-labs/publications-and-media/publications/a-mathematical-theory-of-communication/">Shannon’s paper, Bell Labs</a>; <a href="https://www.asc-cybernetics.org/CofC/">Mead’s address, American Society for Cybernetics</a>. The timeline links individual historical sources.</p></section>
<section class="card" id="practice"><h2>Put the loop into your own words</h2><p>Before moving on, explain one update with its current state, report, target, correction, and next state. Then explain how changing report age or response strength changes that calculation. Use a specific row rather than only saying “feedback happened.”</p><div class="grid"><div><h3>Practice and investigate</h3><ul><li><a href="../demos/cybernetics.html">Explorer: reveal, compare, then change one setting</a></li><li><a href="../labs/week5_lab.html">Laboratory: four guided investigations</a></li><li><a href="../applications/week5_application.html">Greenhouse application: explain a decision</a></li></ul></div><div><h3>Connect and communicate</h3><ul><li><a href="../applications/week5_ai.html">Learning application: change a weight from an error</a></li><li><a href="../discussions/week5_discussion.html">Discussion: feedback in everyday life</a></li><li><a href="Math107_Chapter_05.pdf">Illustrated chapter, review, and solutions</a></li></ul></div></div><p>Week 6 follows money balances through repeated updates. The setting changes, but the habit carries over: name the state, define one step, state the rule, and use the result as the next input.</p></section>
'''
page('readings/week5_reading.html','Reading','When information changes what happens next.','Build a feedback loop from familiar sequences, then discover how timing, response strength, and measurement shape its behavior.',reading,['Recursion & meaning','Worked updates & exact graphics','Feedback in human systems'],nextlink=('Explore the sequences','demos/cybernetics.html'))
SCHEMA=json.loads((ROOT/'scripts/week5_response_contracts.json').read_text())
def oldselect(file,id,label,answer,hint):
 field=next(x for x in SCHEMA[file] if x['attrs'].get('id')==id)
 return select(id,label,[(v,t) for v,t in field['options'] if v],answer,hint)

explorer=r'''
<section class="card"><div class="kicker">Begin with a prediction</div><h2>Use the same rule, then change one assumption</h2><p>Two greenhouses begin at 64°F, have target 70°F, and correct half of the reported error each hour. One receives the current temperature; the other receives a one-hour-old report. Predict which will first pass 70. Then reveal one update at a time and use the report column to explain what happened.</p><p>In these models, a correction changes the temperature by its full computed amount in one step. We allow both warming and cooling, with no external disturbance or equipment limit. The graphs are illustrations of these rules, not equipment settings for an actual greenhouse.</p>'''+figure('feedback-loop','A temperature report is compared with the target, an action changes the temperature, and the new state is measured again.','A thermostat is a useful mathematical setting because each quantity has a clear role.')+r'''</section>
<section class="card" id="sequence"><div class="kicker">Experiment 1 / The reading’s exact example</div><h2>Reveal the first twelve updates</h2><p>The delayed history is \(x_{-1}=x_0=64\). At step n, the correction is added to the current state \(x_n\). Only its report comes from \(x_{n-1}\).</p><div class="controls"><div class="wide"><label for="sequenceStep">Display through step <output id="stepValue">3</output></label><input id="sequenceStep" type="range" min="0" max="12" step="1" value="3"></div><button type="button" id="previousStep">Previous step</button><button type="button" id="nextStep">Next step</button></div><div class="step-reading"><p id="immediateEq"></p><p id="delayedEq"></p><p id="sequenceInsight" aria-live="polite"></p></div><div class="chart" id="sequencePlot">'''+figure('immediate-delayed','The immediate path approaches 70 from below while the delayed path rises above and then below it.','Enable JavaScript to reveal individual steps and their calculations.')+r'''</div><div class="table-wrap trace" id="sequenceTable"></div><p class="small">The table lists states. The calculation above it describes the update that produced the displayed final state. Display rounding does not alter the internal updates.</p><ol class="steps"><li>Show step 2. The delayed path is at the target. Predict the next correction using its available report.</li><li>Show step 3, then step 4. Explain why the first adds heat and the second adds nothing.</li><li>Show steps 7–12. Compare a later peak with the earlier 71.5°F peak; compare troughs as well.</li></ol></section>
<section class="card" id="rules"><div class="kicker">Experiment 2 / Control the comparison</div><h2>Change strength, delay, or the direction of feedback</h2><p>Choose a preset, record its settings, then change one quantity. “Corrective” uses target minus report. “Amplifying” uses report minus reference, pushing a departure farther in the same direction. Negative values are allowed in this abstract numerical model.</p><div class="controls"><div><label for="feedbackPreset">Starting example</label><select id="feedbackPreset"><option value="reading">Greenhouse: current reports</option><option value="delay">Greenhouse: one-step delay</option><option value="strong">Strong immediate correction</option><option value="cycle">Immediate equal-size swings</option><option value="amplify">Amplifying departure</option></select></div><div><label for="mode">Feedback direction</label><select id="mode"><option value="negative">Corrective</option><option value="positive">Amplifying</option></select></div><div><label for="r">Target / reference (state units)</label><input id="r" type="number" min="-100" max="200" step="1" value="70"></div><div><label for="x0">Starting state (state units)</label><input id="x0" type="number" min="-100" max="200" step="1" value="64"></div><div><label for="k">Response strength k</label><input id="k" type="number" min="0" max="2.8" step="0.05" value="0.5"></div><div><label for="delay">Report age (whole steps)</label><input id="delay" type="number" min="0" max="3" step="1" value="0"></div><div><label for="feedbackHorizon">Updates to display</label><input id="feedbackHorizon" type="number" min="1" max="40" step="1" value="12"></div></div><p class="chart-error" id="feedbackError" role="status"></p><div id="feedbackResults"><div class="formula" id="ruleText"></div><p id="behavior" class="insight"></p><div class="stats"><div class="stat"><span>Final displayed state</span><output id="lastState"></output></div><div class="stat"><span>Largest displayed distance from reference</span><output id="maxDev"></output></div><div class="stat"><span>Crossings to the opposite side</span><output id="crossings"></output></div></div><div class="chart" id="feedbackPlot"></div><p class="small">The vertical scale adjusts to include every displayed point and the reference; compare axis labels before comparing shapes. A crossing counts a switch between sides, allowing exact visits to the reference in between. All pre-start history values are set equal to the starting state.</p><div class="table-wrap trace" id="feedbackTable"></div><p class="control-note">Each row is one update from n to n + 1. There is no extra invented action after the last displayed state. A short trajectory describes the shown steps; it is not by itself a long-run stability test.</p></div><h3>Try these controlled comparisons</h3><ul><li>At k = 0.5, compare report ages 0 and 1, holding everything else fixed.</li><li>With current reports, compare k = 0.5, 1.5, 2, and 2.3. Which gaps shrink, persist, or grow?</li><li>Set the starting state equal to the reference. Why does the ideal model stay there?</li><li>For an amplifying loop, start below its reference. Does amplifying always mean “increasing”?</li></ul></section>
<section class="card" id="measurements"><div class="kicker">Experiment 3 / Precision has a timing context</div><h2>How much do independent averages vary?</h2><p>Assume a steady temperature and unbiased, independent readings. Individual readings have standard deviation σ. The standard deviation of an average of m readings is \(\sigma/\sqrt m\). This calculation describes repeated averages under those assumptions.</p><div class="controls"><div><label for="noisesd">Individual standard deviation σ (°F)</label><input id="noisesd" type="number" min="0.5" max="4" step="0.5" value="2"></div><div><label for="noiseN">Readings in one average m</label><input id="noiseN" type="number" min="1" max="25" step="1" value="4"></div><div><label for="sampleSpacing">Minutes between readings</label><input id="sampleSpacing" type="number" min="1" max="30" step="1" value="1"></div></div><p id="noiseExplanation" class="readout" aria-live="polite"></p><div class="table-wrap" id="noiseTable"></div><p>If the newest reading is current, the oldest in a consecutive batch is (m − 1) intervals old. A moving average mixes different past times; it is not identical to one perfectly accurate delayed reading. If the underlying temperature changes, the steady-state averaging assumptions need reconsideration.</p><p>Try m = 1, 4, and 16. Compare the improvement in precision with the span of time covered. Averaging does not remove a shared sensor bias.</p><p><a href="../labs/week5_lab.html">Continue with the four-part laboratory →</a></p></section>
'''
page('demos/cybernetics.html','Explorer','A correction can arrive too late.','Reveal the greenhouse sequences, inspect every update, and test how response strength, report age, and measurement precision affect a model.',explorer,['Step-by-step reveal','Three controlled experiments','Graphs with numerical tables'],nextlink=('Work the guided laboratory','labs/week5_lab.html'))

labfile='labs/week5_lab.html'
ls=lambda *a:oldselect(labfile,*a)
lab=r'''
<section class="card"><div class="kicker">The laboratory / Four connected investigations</div><h2>Observe, compare, act, and observe again</h2><p>The arithmetic is deliberately manageable so you can explain the role of every number. Read the <a href="../readings/week5_reading.html">chapter</a> first and keep the <a href="../demos/cybernetics.html">explorer</a> available. Compute a few updates by hand before using its table.</p><p>Work in order. Each response receives its own numerical or choice feedback. Written explanations save for your instructor’s review; the page does not grade them by length or keywords. Your responses save in this browser. Enter your name at the bottom to print or save a completed copy; submit it through your class system as directed.</p>'''+figure('subscript-timeline','Subscripts label earlier history, starting state, and states after successive updates.','Four state values x₀ through x₃ correspond to three updates. A delayed rule also needs history from before x₀.')+r'''<div class="example"><h3>Keep a row for each decision</h3><p>Write current state, available report, reported error, correction, and next state. For current reports those first two numbers agree; with delay they may differ.</p></div></section>'''+progress()+r'''
<section class="card lab-part" id="part1" data-check-group="1"><div class="kicker">Part 1 / Find the loop</div><h2>Identify the condition, goal, measurement, and action</h2><p>A classroom is at 64°F. Its thermostat is set to 70°F. A temperature sensor supplies a reading, and the controller can turn a heater on or off. Name the parts without confusing a display with something that changes the room.</p><div class="grid">'''+ls('p1state','What is the current state?','64','State means the current condition, before the next action.')+ls('p1ref','What is the reference value?','70','The reference is the desired temperature.')+ls('p1measure','What provides the measurement?','sensor','A measurement reports the condition; the target is a goal.')+ls('p1action','What action changes the state?','heater','The actuator changes the physical temperature.')+r'''</div>'''+written('loopTrace','Trace the loop in one sentence: how does the action change what will be measured next?')+check()+r'''</section>
<section class="card lab-part" id="part2" data-check-group="2"><div class="kicker">Part 2 / Use the current report</div><h2>Remove half of the remaining error</h2><p>For the numerical greenhouse, use target 70°F, starting state \(x_0=64\), and strength \(k=0.5\). Each update changes the temperature by the full computed correction. The report is current and exact; ignore external disturbances.</p><div class="formula">\[e_n=70-x_n,\quad c_n=0.5e_n,\quad x_{n+1}=x_n+c_n.\]</div><div class="example"><h3>A different pair of numbers</h3><p>With start 20, target 28, and strength 0.25, the first error is 8, correction 2, and next state 22. The second error is 6, correction 1.5, and next state 23.5. Use the new remaining error each time.</p></div><div class="grid three">'''+num('p2e0','Initial error e₀ (°F)',6,'Subtract current 64 from target 70.',.02)+num('p2c0','First correction (°F)',3,'Multiply the first error by 0.5.',.02)+num('p2x1','Next state x₁ (°F)',67,'Add the first correction to 64.',.02)+num('p2e1','New error e₁ (°F)',3,'Use target minus the new x₁.',.02)+num('p2c1','Second correction (°F)',1.5,'Take half of the remaining error.',.02)+num('p2x2','Next state x₂ (°F)',68.5,'Add the second correction to x₁.',.02)+r'''</div>'''+written('currentReason','Why does the second correction differ from the first? Identify which temperature was used in each error.')+check()+r'''</section>
<section class="card lab-part" id="part3" data-check-group="3"><div class="kicker">Part 3 / Change only report age</div><h2>Current state plus a correction based on the past</h2><p>Now use \(x_{n+1}=x_n+0.5(70-x_{n-1})\), with \(x_{-1}=x_0=64\). The first two updates give \(x_1=67\) and \(x_2=70\). To find \(x_3\), start at the current \(x_2\), but use the report \(x_1\). To find \(x_4\), start at \(x_3\), but use report \(x_2\).</p>'''+table(['Next state sought','Current state to change','Available report'],[['x₃','x₂ = 70','x₁ = 67'],['x₄','Your x₃','x₂ = 70']])+r'''<div class="grid three">'''+num('p3old2','Old reading used to find x₃ (°F)',67,'The update from step 2 to 3 uses x₁ as its report.',.02)+num('p3corr2','Correction at step 2 (°F)',1.5,'Compute 0.5(70 − x₁).',.02)+num('p3x3','Next state x₃ (°F)',71.5,'Add that correction to current x₂ = 70.',.02)+num('p3old3','Old reading used to find x₄ (°F)',70,'The update from step 3 to 4 uses x₂ as its report.',.02)+num('p3corr3','Correction at step 3 (°F)',0,'Compare the old report of 70 with target 70.',.02)+num('p3x4','Next state x₄ (°F)',71.5,'A zero correction leaves the current state unchanged.',.02)+r'''</div>'''+written('delayZero','Explain why zero reported error in the second row does not establish that the present temperature is at 70°F.')+check()+r'''</section>
<section class="card lab-part" id="part4" data-check-group="4"><div class="kicker">Part 4 / Follow the return</div><h2>Continue the sequence and read its graph</h2><p>Use your delayed values \(x_3=x_4=71.5\). To find \(x_5\), use current \(x_4\) and report \(x_3\). Continue without substituting a current temperature for an old report.</p><div class="grid three">'''+num('p4x5','State x₅ (°F)',70.75,'Compute 71.5 + 0.5(70 − 71.5).',.02)+num('p4x6','State x₆ (°F)',70,'Use x₅ as current and x₄ = 71.5 as the report.',.02)+num('p4x7','State x₇ (°F)',69.625,'Use x₆ as current and x₅ as the report.',.02)+r'''</div>'''+figure('immediate-delayed','Immediate feedback approaches 70 from below. Delayed feedback crosses above and then below the target.','Check that your computed states appear at the right steps. Lines connect the discrete states; they do not specify the within-hour path.')+ls('p4which','Which of these two systems moves above and below the target?','delayed','Compare both paths with the dashed 70°F reference.')+written('p4why','Explain the delayed overshoot using a specific current state, an earlier report, and the resulting correction.')+check()+r'''<p>Then use the explorer with current reports and strength 1.5. It also oscillates. Explain why delay is one possible cause of overshoot, rather than its definition.</p></section>
'''
page(labfile,'Laboratory','Follow every number around the loop.','Four investigations follow a thermostat and compare current and delayed feedback.',lab,['Four investigations','Feedback beside each answer','Autosave & named printing'],store='math107_week5_cybernetics_v4',legacy='math107_week5_cybernetics_v3',nextlink=('Apply the greenhouse model','applications/week5_application.html'))
appfile='applications/week5_application.html'
app=r'''
<section class="card"><div class="kicker">The decision / Same equipment, different information</div><h2>Would you heat a greenhouse that is already warm enough?</h2><p>A greenhouse begins at 64°F with target 70°F. Its numerical controller corrects half of the reported difference each hour. Compare two reporting arrangements: a current reading and a one-hour-old reading. Assume the same equipment, exact reports about their own times, no outside disturbance, and the ability to warm or cool by the full calculated amount.</p><p>Your goal is to approach 70°F without crossing it in this model. Compare the arrangements on that stated goal. A useful recommendation needs a calculation, an explanation of the mechanism, and an acknowledgment of what the model leaves out.</p>'''+figure('feedback-loop','A greenhouse thermometer sends a report; a controller compares it with 70 degrees; heating or cooling changes the temperature and the next reading.','Name each role: temperature is the state, thermometer the sensor, 70°F the reference, the update rule the controller, and heater or fan the actuator.')+r'''</section>
<section class="card" data-check-group="1"><div class="kicker">Part A / Build the comparison</div><h2>Compute three updates for each arrangement</h2><div class="grid"><div><h3>Current information</h3><p>Start at \(x_0=64\). Use \(x_{n+1}=x_n+0.5(70-x_n)\).</p>'''+num('now1','Current-report temperature x₁ (°F)',67,'Start at 64 and add half of 70 − 64.',.015)+num('now2','Current-report temperature x₂ (°F)',68.5,'Use the new x₁ in both current-state and report positions.',.015)+num('now3','Current-report temperature x₃ (°F)',69.25,'Use x₂, then add half of its remaining difference from 70.',.015)+r'''</div><div><h3>One-step-old information</h3><p>Start at \(x_{-1}=x_0=64\). Use \(x_{n+1}=x_n+0.5(70-x_{n-1})\).</p>'''+num('late1','Delayed-report temperature x₁ (°F)',67,'The current and pre-start temperatures are both 64.',.015)+num('late2','Delayed-report temperature x₂ (°F)',70,'Start at current x₁ = 67 but use report x₀ = 64.',.015)+num('late3','Delayed-report temperature x₃ (°F)',71.5,'Start at current x₂ = 70 but use report x₁ = 67.',.015)+r'''</div></div>'''+check()+r'''<div class="example"><h3>Use separate places for now and the report</h3><p>At the update from step 1 to step 2, both arrangements start at 67. One uses a 67 report, so it adds 1.5. The other uses a 64 report, so it adds 3. The delay changes the correction, not the current starting point.</p></div></section>
<section class="card" data-check-group="2"><div class="kicker">Part B / A report can hide a present mismatch</div><h2>Make and support a decision</h2>'''+figure('delay-decision','A delayed 67 degree report causes a plus 1.5 correction to a current 70 degree state, producing 71.5.','The report is accurate about an earlier hour. Its age makes the next action unsuitable for the current state.')+oldselect(appfile,'choice','Which arrangement better meets the stated goal of approaching 70°F without crossing it?','immediate','Compare the first three updates, with all other assumptions fixed.')+num('correction','The delayed greenhouse is now at 71.5°F, but its available report is 70°F. What correction does the rule call for (°F)?',0,'The controller uses 0.5(70 − reported 70), even though the current state is higher.',.015)+written('reason','Write a recommendation using both sequences. Explain one overshoot with its current state, old report, and correction. Then explain why a zero correction can leave the greenhouse above target.')+check()+r'''</section>
<section class="card"><div class="kicker">Part C / Test a possible adjustment</div><h2>What if we keep the delay but use a gentler response?</h2><p>In the <a href="../demos/cybernetics.html#rules">explorer</a>, set target 70, start 64, report age 1, and 20 updates. Compare k = 0.5 with k = 0.2. Change only the response strength. Record the first few temperatures and the largest temperature shown. Explain what improves and what becomes slower.</p>'''+written('gentlerComparison','Record the two strengths, selected states, and observed overshoot or approach. Keep claims tied to the displayed horizon and this model.')+r'''<p>A real controller may also need to model thermal inertia, weather, heating limits, and different costs of being too warm or too cold. A graph of a simplified rule can test an explanation, but it cannot supply all those operational choices.</p></section>
<section class="card"><h2>Information quality is part of the decision</h2><p>Suppose readings also vary randomly. Averaging several independent readings can improve precision under a steady-temperature assumption. Collecting them can introduce waiting, and a past average can lag a changing present. Ask whether the improvement in precision is useful soon enough to guide the action.</p>'''+written('sensorRecommendation','Propose one additional measurement or check before recommending an actual controller. Explain how it addresses noise, bias, delay, or a missing physical effect.')+r'''<p>Before submitting, distinguish a mathematical comparison of two settings from a recommendation for real equipment. Your completed work should make the assumptions and the stated goal visible.</p></section>
'''
page(appfile,'Application','Correcting a condition that has already changed.','Compare two greenhouse reporting arrangements, explain a delayed overshoot, and test a gentler response while keeping the modeling assumptions explicit.',app,['A concrete decision','Two sequences, one changed assumption','Saved explanations'],store='math107_week5_greenhouse_delay_v3',legacy='math107_week5_greenhouse_delay_v2',nextlink=('Connect feedback to learning','applications/week5_ai.html'))

aifile='applications/week5_ai.html'
ai=r'''
<section class="card"><div class="kicker">The mathematical setting / One adjustable number</div><h2>Making a prediction is different from learning from its result</h2><p>A calculator can repeat a fixed calculation without changing its rule. A learning process adds a return path: make a prediction, compare it with a target, and change an adjustable part before trying again. Here we can see that entire loop with a single number.</p><p>Let the input be 2, the target output be 6, and an adjustable weight be w. The prediction is \(\widehat y=2w\); the hat means “predicted value.” This is a deliberately tiny model with one fixed training example. It shows the structure of an update, not how to build a full neural network or judge its performance on new data.</p>'''+figure('learning-updates','Weights 1, 2, 2.5, and 2.75 yield predictions 2, 4, 5, and 5.5. The weights approach 3 while the predictions approach target 6.','Weight and prediction are different quantities. A successful weight here is 3 because 2 × 3 = 6.')+r'''</section>
<section class="card"><div class="kicker">The rule / Prediction → error → weight change</div><h2>Follow one attempt all the way through</h2><div class="formula">\[\widehat y_n=2w_n,\quad e_n=6-\widehat y_n,\quad w_{n+1}=w_n+0.25e_n.\]</div><p>Start with \(w_0=1\). The prediction is 2, so the error is 4. A quarter of that error is 1. Add it to the <em>weight</em> to get \(w_1=2\). The next prediction is therefore 4. We did not simply add the error to the prediction.</p>'''+table(['Attempt','Current weight','Prediction','Error','Weight correction','Next weight'],[['0','1','2','4','1','2'],['1','2','4','2','0.5','2.5'],['2','2.5','5','1','0.25','2.75'],['3','2.75','5.5','0.5','0.125','2.875']])+r'''<p>Rearranging gives \(w_{n+1}=w_n+0.5(3-w_n)\). That is the same half-gap rule as the immediate greenhouse, with a weight target of 3. Different settings can share the same mathematics.</p></section>
<section class="card" data-check-group="1"><h2>Your turn: use a weight of 2</h2><div class="grid">'''+num('q1','With w = 2, what prediction does 2w make?',4,'Multiply the weight 2 by input 2.')+num('q2','With target 6 and prediction 4, what is the signed error?',2,'Compute target minus prediction: 6 − 4.')+num('q3','With w = 2 and error 2, what is the next weight?',2.5,'Add 0.25 × 2 to the current weight 2.')+oldselect(aifile,'q4','Why is this training process a feedback loop?','feedback','Information about the earlier result changes the next attempt.')+r'''</div>'''+written('learningExplanation','Explain the roles of the input, current weight, prediction, target, error, and next weight. State why reaching this one target does not establish success on other inputs.')+check()+r'''</section>
<section class="card" id="learning"><div class="kicker">Investigate / How strong and how current is the update?</div><h2>Compare current and one-attempt-old errors</h2><p>Replace 0.25 with a chosen step size α. The current rule is \(w_{n+1}=w_n+\alpha(6-2w_n)\). The delayed rule uses \(w_{n-1}\) inside the parentheses, with \(w_{-1}=w_0\). The current weight still receives the correction.</p><div class="controls"><div><label for="learningAlpha">Weight step size α</label><input id="learningAlpha" type="number" min="0" max="1.2" step="0.05" value="0.25"></div><div><label for="learningStart">Starting weight w₀</label><input id="learningStart" type="number" min="-5" max="10" step="0.5" value="1"></div><div><label for="learningSteps">Updates to display</label><input id="learningSteps" type="number" min="1" max="30" step="1" value="10"></div><div><label for="learningTrace">Show update details for</label><select id="learningTrace"><option value="now">Current error</option><option value="late">One-attempt-old error</option></select></div></div><p id="learningSummary" class="readout" aria-live="polite"></p><div class="chart" id="learningPlot"></div><div class="table-wrap trace" id="learningTable"></div><p class="small">The graph shows predictions, while the table includes weights and the reported prediction used in each correction. Values are rounded for display; calculations keep precision.</p><ol class="steps"><li>At α = 0.25, compare the current and delayed paths. Which reported error is still positive when the delayed prediction has reached 6?</li><li>Use α = 0.75. Explain a current-error overshoot using the weight update.</li><li>Use α = 0. Compare this with learning that changes a parameter.</li></ol>'''+written('learningInvestigation','Record an update from each timing arrangement at the same step size. Explain the effect of timing, then describe what changed at a larger step size.')+r'''</section>
<section class="card"><h2>What backpropagation contributes</h2><p>A large neural network has many adjustable weights and a loss that summarizes prediction error. <em>Backpropagation</em> computes how that loss changes with each weight, working backward through the computations. An optimization rule uses those sensitivities to choose parameter updates. The flow of error information and the rule choosing the update are related but distinct tasks.</p><p>Our rule is chosen so its arithmetic is visible. It is not a universal formula for neural-network training. In the example, prediction uses the current weight without altering it; training adds the comparison and weight update around that pass. Changing parameters to fit one example does not guarantee useful predictions elsewhere.</p><p class="small">Primary source: <a href="https://doi.org/10.1038/323533a0">Rumelhart, Hinton, and Williams, “Learning representations by back-propagating errors” (1986)</a>.</p></section>
<section class="card"><h2>Learning also depends on the quality of the evidence</h2><p>Targets and examples can contain variation, bias, or measurement mistakes. A large response to one unusual example can follow noise rather than a reliable pattern. Multiple observations may help, but they need to represent the setting where the model will be used.</p>'''+written('learningEvidence','Suppose a model changes strongly after one unusually high sensor reading. What additional evidence would help distinguish a real change from noise? What could waiting cost?')+r'''<p>The optional <a href="ai_week5.html">Surprise, Information, and Cross-Entropy extension</a> asks a related question: how can we score a prediction that assigns probabilities instead of a single number?</p></section>
'''
page(aifile,'AI Application','Learning returns an error to the next attempt.','Trace a toy predictor from one adjustable weight through a prediction, an error, and an update; compare strong and delayed responses.',ai,['One weight, one clear example','Current & delayed training','Limits of a model'],store='math107_week5_learning_v1',nextlink=('Score probabilistic predictions','applications/ai_week5.html'))

extfile='applications/ai_week5.html'
ext=r'''
<section class="card"><div class="kicker">Optional extension / A different kind of prediction</div><h2>How can we score the probability assigned to what happened?</h2><p>In the <a href="week5_ai.html">learning application</a>, a predictor produced a number and we calculated target minus prediction. A text predictor instead assigns probabilities to possible next tokens. A <em>token</em> is a unit of text used by a model; it may be a word, part of a word, or punctuation.</p><p>Suppose the observed next token is “rain.” Model A assigned it probability 1/2; Model B assigned it 1/8. The outcome was less surprising under A. We can score the probability given to the token that actually occurred, then average that score over a sequence. These probabilities and text examples are invented for instruction.</p><div class="insight"><h3>Where this fits</h3><p>This is a scoring rule, not a complete training algorithm. During training, information from a loss can guide later parameter changes, closing a feedback loop. A lower score on one token is evidence about that token only.</p></div></section>
<section class="card"><h2>Use powers of two before logarithms</h2><p>Information surprisal is \(I=-\log_2(p)\) bits for an observed event assigned probability p. Read this through familiar powers: if \(p=1/2^k\), then \(I=k\). The probability 1/8 is \(1/2^3\), giving 3 bits. The logarithm is the inverse question, “which power of two gives this reciprocal?”</p>'''+figure('information-bits','Probabilities one half, one quarter, one eighth, and one sixteenth correspond to 1, 2, 3, and 4 bits of surprise.','Each halving of the probability assigned to the observed event adds one bit to its surprisal.')+r'''<p>A certain event, p = 1, has surprise 0. An event given p = 0 has infinite surprise if it occurs; the model assigned no probability to an observed outcome. The interactive calculator requires a positive probability so its finite score can be displayed.</p><div class="controls"><div><label for="tokenProbability">Probability of the observed token (0 &lt; p ≤ 1)</label><input id="tokenProbability" type="text" inputmode="decimal" value="1/8"></div></div><p id="surpriseSummary" class="readout" aria-live="polite"></p><p>Try 1/2, 1/8, 1/32, and 1. Then try 0 and explain why it has no finite score.</p></section>
<section class="card"><h2>Average the scores of the observed tokens</h2><p>For four observed tokens, suppose a model assigned probabilities 1/2, 1/4, 1/8, and 1/4. The surprisals are 1, 2, 3, and 2 bits. The total is 8 bits and the mean is 2 bits per token. This empirical average negative log probability is commonly called cross-entropy loss for the observed sequence.</p><p><em>Perplexity</em> is \(2^H\) when the mean score H is measured in bits per token. With H = 2, perplexity is 4. For intuition, a uniform prediction over four possible alternatives has surprisal 2 bits for whichever occurs. Perplexity is an effective uncertainty scale, not a literal count of a model’s vocabulary or proof that every prediction offered four choices.</p></section>'''+progress()+r'''
<section class="card" data-check-group="1"><h2>1. Convert three probabilities to bits</h2><div class="grid three">'''+num('q1a','Surprise when p = 1/2 (bits)',1,'Write the probability as 1/2 to a power.')+num('q1b','Surprise when p = 1/8 (bits)',3,'Since 8 = 2³, the exponent is 3.')+num('q1c','Surprise when p = 1/32 (bits)',5,'Find k such that 2 to the k equals 32.')+r'''</div>'''+check()+r'''</section>
<section class="card" data-check-group="2"><h2>2. Score the four observed tokens</h2><p>Their surprises are 1, 2, 3, and 2 bits.</p><div class="grid">'''+num('q2a','Total surprise (bits)',8,'Add all four token scores.')+num('q2b','Average surprise (bits per token)',2,'Divide the total by four observed tokens.')+r'''</div>'''+check()+r'''</section>
<section class="card" data-check-group="3"><h2>3. Compare two models on the same observed token</h2><p>Model A assigned its observed token probability 1/2; Model B assigned that same token probability 1/8.</p><div class="grid three">'''+num('q3a','Model A surprise (bits)',1,'Convert 1/2 to its surprisal.')+num('q3b','Model B surprise (bits)',3,'Convert 1/8 to its surprisal.')+oldselect(extfile,'q3c','Which has the lower loss for this token?','A','Choose the smaller surprise for the token that actually occurred.')+r'''</div>'''+written('tokenComparison','Why is this one-token result insufficient to conclude which model predicts better across a whole task?')+check()+r'''</section>
<section class="card" data-check-group="4"><h2>4. Convert an average to perplexity</h2>'''+num('q4','If H = 2 bits per token, what is 2ᴴ?',4,'Compute 2². This quantity is not measured in bits.')+check()+r'''</section>
<section class="card" data-check-group="5"><h2>5. Connect the score to idealized coding</h2><p>Under a known probability model, surprise gives an idealized coding-length scale. For long sequences, coding methods can approach the total negative log probability, apart from coding overhead. An individual fractional-bit score is not a literal fraction of a stored bit for a single isolated token.</p>'''+num('q5','About how many idealized bits for 100 tokens averaging 2 bits per token?',200,'Multiply the token count by the average bits per token.')+check()+r'''</section>
<section class="card"><h2>Keep three information questions distinct</h2>'''+table(['Quantity','What is averaged or scored?','Example'],[['Surprisal','One observed outcome under a model','p = 1/8 gives 3 bits'],['Entropy','Surprise averaged over the source’s possible outcomes','A fair coin has entropy 1 bit per toss'],['Empirical cross-entropy loss','Model surprise averaged over observed outcomes','Four token scores 1, 2, 3, 2 average to 2']])+r'''<p>These quantities connect prediction and coding. They do not measure truthfulness, fairness, usefulness, or understanding by themselves. Training software often uses natural logarithms, giving nats rather than bits; changing the logarithm base changes units, not which positive-probability prediction has the lower loss.</p>'''+written('scoringReflection','Connect scoring to feedback: what information returns after an observed token, what could be updated, and what additional evidence would be needed to judge useful performance?')+r'''<p class="small">Primary source for information and coding: <a href="https://www.nokia.com/bell-labs/publications-and-media/publications/a-mathematical-theory-of-communication/">Claude Shannon, A Mathematical Theory of Communication (1948)</a>. Use the timeline’s coin experiment to compare entropy with a single observed surprisal.</p></section>
'''
page(extfile,'AI Mathematics Extension','Score a prediction by its surprise.','Use powers of two to connect probabilities, bits, average token loss, perplexity, and an idealized coding length.',ext,['Optional information-theory extension','Worked probability scores','All original practice retained'],store='math107_ai_week5_v2',legacy='math107_ai_week5_v1',nextlink=('Return to the feedback discussion','discussions/week5_discussion.html'))

